// ===== 1. 验证事件循环阶段执行顺序 =====
const fs = require('fs');

fs.readFile(__filename, () => {
  // 在 I/O 回调（poll 阶段）内部：
  setImmediate(() => console.log('1. setImmediate'));  // check 阶段
  process.nextTick(() => console.log('2. nextTick'));    // 微任务，当前阶段后
  Promise.resolve().then(() => console.log('3. Promise')); // 微任务，nextTick 后
  setTimeout(() => console.log('4. setTimeout'), 0);    // 下一轮 timers
});
// 输出顺序：2 → 3 → 1 → 4

// ===== 2. Stream 背压处理 =====
const { createReadStream, createWriteStream } = require('fs');

function copyWithBackpressure(src, dest) {
  const readable = createReadStream(src);
  const writable = createWriteStream(dest);

  readable.on('data', (chunk) => {
    const canContinue = writable.write(chunk);
    if (!canContinue) {
      // 写缓冲区满（达到 highWaterMark），暂停读取
      readable.pause();
    }
  });

  // 写缓冲区排空后恢复读取
  writable.on('drain', () => {
    readable.resume();
  });

  readable.on('end', () => {
    writable.end(); // 关闭写入流
  });
}

// ===== 3. 推荐写法：pipeline 自动处理背压和错误 =====
const { pipeline } = require('stream');
const { createGzip } = require('zlib');

pipeline(
  createReadStream('input.txt'),
  createGzip(),
  createWriteStream('input.txt.gz'),
  (err) => {
    if (err) console.error('Pipeline failed:', err);
    else console.log('Pipeline succeeded');
  }
);

// ===== 4. 自定义 Transform =====
const { Transform } = require('stream');

class LineCounter extends Transform {
  constructor() {
    super();
    this.count = 0;
  }
  _transform(chunk, encoding, callback) {
    const lines = chunk.toString().split('\n').length - 1;
    this.count += lines;
    callback();
  }
  _flush(callback) {
    this.push(String(this.count));
    callback();
  }
}

